INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Standardsoftware immer günstiger als Fachsoftware?', 2, '[{"text": "Ja", "correct": true, "because": "Breitere Nutzung senkt Kosten"}, {"text": "Nein", "correct": false, "because": "Spezielle Standardlösungen können teuer sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Software wähle ich für einfache Textverarbeitung?', 3, '[{"text": "Standardsoftware", "correct": true, "because": "Allgemeine Tools wie Office reichen"}, {"text": "Fachsoftware", "correct": false, "because": "Zu spezialisiert"}, {"text": "Kostenlose Beta-Version", "correct": false, "because": "Weniger stabil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine Anwendung für CAD geeignet?', 5, '[{"text": "Spezialisierte Funktionen", "correct": true, "because": "Präzise Konstruktion nötig"}, {"text": "Hohe Performance", "correct": true, "because": "Komplexe Berechnungen"}, {"text": "Einfache Bedienung", "correct": false, "because": "Sekundär bei Fachsoftware"}, {"text": "Niedrige Kosten", "correct": false, "because": "Qualität zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Fachsoftware ist immer teurer. b) Standardsoftware ist flexibler.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Standard ist oft starr"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist meist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist oft richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl einer Software für Buchhaltung?', 4, '[{"text": "Spezifische Funktionen", "correct": false, "because": "Wichtig für Fachaufgaben"}, {"text": "Kompatibilität", "correct": false, "because": "Muss mit Systemen passen"}, {"text": "Gaming-Features", "correct": true, "because": "Irrelevant für Buchhaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Standardsoftware mehr Updates braucht als Fachsoftware?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Anbieter ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für eine CRM-Software entscheidend?', 3, '[{"text": "Kundendatenverwaltung", "correct": true, "because": "Kern der Aufgabe"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Nicht nötig"}, {"text": "Kostenlosigkeit", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Standardsoftware?', 5, '[{"text": "Breite Verfügbarkeit", "correct": true, "because": "Viele Nutzer, einfacher Support"}, {"text": "Geringere Kosten", "correct": true, "because": "Massenproduktion"}, {"text": "Hohe Spezialisierung", "correct": false, "because": "Eher bei Fachsoftware"}, {"text": "Exklusive Features", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Fachsoftware ist schwer zu lernen. b) Standardsoftware ist immer ausreichend. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft zu allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist oft richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist meist wahr"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Bildbearbeitungssoftware?', 4, '[{"text": "Hohe Performance", "correct": false, "because": "Für große Dateien nötig"}, {"text": "Spezifische Werkzeuge", "correct": false, "because": "Kern der Anwendung"}, {"text": "Einfache Tabellenkalkulation", "correct": true, "because": "Anderer Anwendungsbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Fachsoftware immer für Experten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für spezifische Laien geeignet"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für eine ERP-Software entscheidend?', 4, '[{"text": "Integration", "correct": true, "because": "Prozesse vernetzen"}, {"text": "Spezialisierung", "correct": true, "because": "Branchenspezifisch"}, {"text": "Gaming-Optimierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Standardsoftware keine Anpassungen erlaubt. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Meist vorgefertigt"}, {"text": "Nein", "correct": false, "because": "Manche bieten Optionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für eine Software im Büro?', 3, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Effizienz für alle"}, {"text": "Maximale Spezialisierung", "correct": false, "because": "Sekundär"}, {"text": "Hohe Kosten", "correct": false, "because": "Budget zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Fachsoftware ist branchenspezifisch. b) Standardsoftware ist immer Open Source.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft proprietär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat Standardsoftware?', 5, '[{"text": "Geringe Anpassbarkeit", "correct": true, "because": "Wenig Flexibilität"}, {"text": "Allgemeine Funktionen", "correct": true, "because": "Nicht spezialisiert"}, {"text": "Hohe Kosten", "correct": false, "because": "Oft günstiger"}, {"text": "Schwere Bedienung", "correct": false, "because": "Meist einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Software für Datenanalyse unwichtig?', 3, '[{"text": "Statistische Tools", "correct": false, "because": "Kern der Aufgabe"}, {"text": "Datenverarbeitung", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Spiele-Engine", "correct": true, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht Fachsoftware immer Schulungen?', 3, '[{"text": "Ja", "correct": true, "because": "Oft komplexer"}, {"text": "Nein", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Standardsoftware für alle Branchen passt?', 2, '[{"text": "Nein", "correct": true, "because": "Zu allgemein für Spezialfälle"}, {"text": "Ja", "correct": false, "because": "Eingeschränkte Anpassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Software wähle ich für Projektmanagement?', 4, '[{"text": "Fachsoftware", "correct": true, "because": "Spezifische Tools nötig"}, {"text": "Standardsoftware", "correct": false, "because": "Zu allgemein"}, {"text": "Kostenlose App", "correct": false, "because": "Weniger Funktionen"}]');
